import { Column, Entity, Index } from 'typeorm';
import { BaseEntity } from './base.entity';
import {
  PaymentGatewayType,
  PaymentMethod,
} from '../enums/enums';

/**
 * A payment option an admin configures and a customer picks at checkout.
 *
 * `slug` is always generated by the backend from `name` — it is the value stored
 * on `Payment.method`, so it doubles as the stable identifier for reports.
 *
 * Two flavours share one table:
 *  - manual (`isManual = true`): the customer pays to the account configured
 *    here and submits proof (txnId for MFS, account details for Bank). Stored
 *    on `Payment.metaData`.
 *  - automated (`isManual = false`): `provider` binds the gateway to an existing
 *    PaymentMethod so the current gateway-callback settlement flow is reused.
 */
@Entity()
export class PaymentGateway extends BaseEntity {
  @Column({ type: 'varchar', length: 250 })
  name: string;

  @Column({ type: 'varchar', length: 250 })
  nameBN: string;

  @Column({ type: 'varchar', length: 250, unique: true })
  @Index()
  slug: string;

  @Column({ type: 'varchar', length: 20, default: PaymentGatewayType.MFS })
  type: string;

  /** Manual gateways never redirect — the customer pays and submits proof. */
  @Column({ default: false })
  isManual: boolean;

  /** Existing PaymentMethod an automated gateway settles through. */
  @Column({ type: 'varchar', length: 20, nullable: true })
  provider: string;

  /** Rich text (sanitized HTML) shown to the customer with this gateway. */
  @Column({ type: 'text', nullable: true })
  description: string;

  @Column({ type: 'text', nullable: true })
  iconUrl: string;

  @Column({ type: 'text', nullable: true })
  iconPath: string;

  @Column({ default: true })
  isActive: boolean;

  // ---- manual MFS + manual Bank account details ----

  @Column({ type: 'varchar', length: 250, nullable: true })
  accountName: string;

  @Column({ type: 'varchar', length: 100, nullable: true })
  accountNumber: string;

  @Column({ type: 'varchar', length: 250, nullable: true })
  bankName: string;

  @Column({ type: 'varchar', length: 250, nullable: true })
  branchName: string;
}